import csv, collections as c, statistics as s
from datetime import datetime
from itertools import product
def read(n):
 return list(csv.DictReader(open('data/'+n+'.csv')))
I,A,S=map(read,['incidents','activity','staffing'])
a={r['incident_id']:r for r in A}
assert len(a)==len(A) and len({r['incident_id'] for r in I})==len(I)
assert set(a)<={r['incident_id'] for r in I}
for r in I:
 d=r['opened_at'][:10];r['d']=d;r['day']=int(d[-2:])
 assert (r['day']>=8)==(r['workflow']=='assist'),r
 if r['incident_id'] in a:
  r.update(a[r['incident_id']])
  r['t']=(datetime.fromisoformat(r['closed_at'].replace('Z','+00:00'))-datetime.fromisoformat(r['opened_at'].replace('Z','+00:00'))).total_seconds()/60
  assert r['t']>=0
  for k in ('responder_minutes','handoffs','reopened_within_72h'):r[k]=int(r[k])
def group(rows,ks):
 g=c.defaultdict(list)
 for r in rows:g[tuple(r[k] for k in ks)].append(r)
 return g
def summ(rows):
 b=[r for r in rows if 't' in r]
 if not b:return (len(rows),0)
 t=sorted(r['t'] for r in b); m=[r['responder_minutes'] for r in b]
 return len(rows),len(b),s.median(t),round(s.mean(t),1),t[(9*len(t)+9)//10-1],round(s.mean(m),2),sum(m),round(s.mean(r['handoffs'] for r in b),2),sum(r['reopened_within_72h'] for r in b),sum(x>10080 for x in t),sum(x<=1440 for x in t)
for ks in [('workflow',),('workflow','severity'),('workflow','service_group','severity'),('workflow','intake_channel'),('d',)]:
 print('GROUP',ks)
 for k,v in sorted(group(I,ks).items()):print(k,summ(v))
print('missing',[(r['day'],r['service_group'],r['severity'],r['intake_channel'],r['workflow']) for r in I if 't' not in r])
print('staffing')
for r in S:
 assert int(r['incidents_opened'])==len(group(I,('d','service_group'))[(r['date'],r['service_group'])])
 print(*r.values())
def wm(vals):
 vals=sorted(vals); z=0; half=sum(w for _,w in vals)/2
 for x,w in vals:
  z+=w
  if z>=half-1e-8:return x
for keys in [('severity',),('severity','service_group'),('severity','service_group','intake_channel')]:
 rows={w:group([r for r in I if r['workflow']==w],keys) for w in ['manual','assist']}
 for target in rows:
  weights={k:len(v) for k,v in rows[target].items()}
  common=set(rows['manual'])&set(rows['assist'])
  print('standardize',keys,target,'overlap',sum(weights[k] for k in common))
  for w in rows:
   vals=[]; mm=tt=0; capped=[]
   for k in common:
    v=[r for r in rows[w][k] if 't' in r]
    if not v:continue
    weight=weights[k]/len(v)
    vals += [(r['t'],weight) for r in v]
    mm+=sum(r['responder_minutes'] for r in v)*weight
    tt+=sum(r['t'] for r in v)*weight
   print(w,wm(vals),mm,tt)
for radius in [1,2,3]:
 print('cutoff',radius)
 for w,v in sorted(group([r for r in I if 8-radius<=r['day']<8+radius],('workflow',)).items()):
  print(w,summ(v),c.Counter(r['severity'] for r in v))
print('staff totals')
for g in ('identity','storage'):
 for week in (0,1):
  rr=[r for r in S if r['service_group']==g and (int(r['date'][-2:])>=8)==week]
  print(g,week,[sum(int(r[k]) for r in rr) for k in list(S[0])[2:]])
for w,v in sorted(group(I,('workflow',)).items()):
 for fill in [0,10080]:
  t=[min(r.get('t',fill),10080) for r in v];print('close bounds',w,fill,s.median(t),s.mean(t))
 print('late reopen followup',sum(r.get('closed_at','')>'2026-06-19T23:59:00Z' for r in v))
